// later node fails and the start-time compensation "release" runs.
assert.deepEqual(calls, ['reserve', 'reserve', 'release'], 'old run compensates with release, not releaseV2');
assert.equal(r2.compensationAttempts[0].operation, 'release');
console.log('old run keeps start-time compensation: OK');

// A new run uses the modified config (reserveV2, 1 attempt, releaseV2).
calls.length = 0;
const r3 = await executeWorkflowAsync(wf3, {}, operations);
assert.equal(r3.status, 'action_failed');
assert.deepEqual(calls, ['reserveV2', 'releaseV2']);
assert.equal(r3.actionAttempts.filter(a => a.nodeId === 'book').length, 1);
assert.equal(r3.compensationAttempts[0].operation, 'releaseV2');
console.log('new run uses modified config: OK');

// Removing compensation entirely on the live node must not affect a parked run;
// and adding compensation later must not pull an old run into compensating.
const bookNode2 = { id: 'book', type: 'action', operation: 'reserve', next: 'after' };
const wf4 = {
  id: 'w', entry: 'start',
  nodes: [
    { id: 'start', type: 'trigger', next: 'wait' },
    { id: 'wait', type: 'action', operation: 'hold', next: 'book' },
    bookNode2,
    failNode,
    { id: 'after', type: 'end', result: 'done' },
  ],
};
let releaseHold3;
const holdGate3 = new Promise(r => { releaseHold3 = r; });
let holdStarted3;
const started3 = new Promise(r => { holdStarted3 = r; });
operations.hold = () => { holdStarted3(); return holdGate3.then(() => 'held'); };
const run4 = executeWorkflowAsync(wf4, {}, operations);
await started3;
await sleep(5);
// add compensation after run started — old run must NOT compensate
bookNode2.compensation = { operation: 'release' };
validateWorkflow(wf4);
releaseHold3();
const r4 = await run4;
assert.equal(r4.status, 'action_failed');
assert.equal(r4.compensationStatus, 'not_needed');
assert.deepEqual(r4.compensationAttempts, []);
console.log('compensation added after start does not reach old run: OK');

// Deleting retry on the live node: parked run still retries per start config.
const bookNode3 = {
  id: 'book', type: 'action', operation: 'reserve',
  retry: { attempts: 3, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 },
  next: 'after',
};
const wf5 = {
  id: 'w', entry: 'start',
  nodes: [
    { id: 'start', type: 'trigger', next: 'wait' },
    { id: 'wait', type: 'action', operation: 'hold', next: 'book' },
    bookNode3,
    { id: 'after', type: 'end', result: 'done' },
  ],
};
let releaseHold4;
const holdGate4 = new Promise(r => { releaseHold4 = r; });
let holdStarted4;
const started4 = new Promise(r => { holdStarted4 = r; });
operations.hold = () => { holdStarted4(); return holdGate4.then(() => 'held'); };
reserveCalls = 0;
operations.reserve = () => { reserveCalls += 1; throw new Error('always'); };
const run5 = executeWorkflowAsync(wf5, {}, operations);
await started4;
await sleep(5);
delete bookNode3.retry;
validateWorkflow(wf5);
releaseHold4();
const r5 = await run5;
assert.equal(r5.status, 'action_failed');
assert.equal(r5.actionAttempts.filter(a => a.nodeId === 'book').length, 3, 'deleted retry still applies as 3 attempts');
console.log('deleted retry config still applies to old run: OK');

// Revalidation that FAILS on another node must not disturb the parked run.
const bookNode4 = {
  id: 'book', type: 'action', operation: 'reserve',
  retry: { attempts: 2, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 },
  next: 'after',
};
const otherNode = { id: 'other', type: 'action', operation: 'noop', next: 'after' };
const wf6 = {
  id: 'w', entry: 'start',
  nodes: [
    { id: 'start', type: 'trigger', next: 'wait' },
    { id: 'wait', type: 'action', operation: 'hold', next: 'book' },
    bookNode4,
    otherNode,
    { id: 'after', type: 'end', result: 'done' },
  ],
};
operations.noop = () => 'ok';
let releaseHold5;
const holdGate5 = new Promise(r => { releaseHold5 = r; });
let holdStarted5;
const started5 = new Promise(r => { holdStarted5 = r; });
operations.hold = () => { holdStarted5(); return holdGate5.then(() => 'held'); };
reserveCalls = 0;
operations.reserve = () => { reserveCalls += 1; return 'reserved'; };
const run6 = executeWorkflowAsync(wf6, {}, operations);
await started5;
await sleep(5);
bookNode4.operation = 'reserveV2';
otherNode.next = 'nowhere'; // break another node
assert.throws(() => validateWorkflow(wf6), /unknown destination/);
releaseHold5();
const r6 = await run6;
assert.equal(r6.status, 'completed');
assert.equal(reserveCalls, 1, 'old run still calls reserve once (first attempt succeeds)');
assert.deepEqual(r6.context.output.book, 'reserved');
console.log('failed revalidation on another node does not affect old run: OK');

// A new run against the invalid definition is rejected before any operation runs.
calls.length = 0;
await assert.rejects(() => executeWorkflowAsync(wf6, {}, operations), /unknown destination/);
assert.equal(calls.length, 0);
console.log('invalid definition rejected before any business operation: OK');

console.log('\nAll scenario checks passed.');
